/* ===== Exam-style wording pass: scenario stems, "What should you do?", select-two items =====
   RW(id, oldStart, newStem) rewrites a stem. RM(id, oldStart, newStem, correct[], wrong[]) also replaces the options.
   Ids never change, so saved progress is kept. The check on oldStart throws if an id ever drifts. */
function q15get(id, s) { const q = Q.find(x => x.id === id); if (!q || q.type || !q.q.startsWith(s)) throw new Error('q15 id ' + id + ' stem mismatch'); return q; }
function RW(id, s, t) { q15get(id, s).q = t; }
function RM(id, s, t, c, w) { const q = q15get(id, s); q.q = t; q.c = c; q.w = w; }
